      let submitted = false;

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#039;");
      }

      function Field({ field, value, error }) {
        const helperId = `${field.id}-helper`;
        const errorId = `${field.id}-error`;
        const describedBy = [
          field.helper ? helperId : "",
          error ? errorId : ""
        ].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}
              ${field.required
                ? '<span class="required-note">(required)</span>'
                : '<span class="optional-note">(optional)</span>'}
            </label>
            ${field.helper ? `<p class="helper-text" id="${helperId}">${field.helper}</p>` : ""}
            <input
