          </div>
        `;
      }

      function SupportContactForm() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">Tell us who you are and how to reach you. Required fields are marked in text.</p>
            <form id="contact-form" novalidate>
              ${fields.map((field) => Field({
                field,
                value: values[field.id],
                error: errors[field.id]
              })).join("")}
              <button type="submit">Submit support request</button>
              <p class="form-status" id="form-status" tabindex="-1" aria-live="polite">
                ${submitted ? "Thanks. Your support request is ready to send." : ""}
              </p>
            </form>
          </section>
        `;
      }

      function validateFields() {
        errors = fields.reduce((currentErrors, field) => {
          const message = field.validate(values[field.id]);
          if (message) {
            currentErrors[field.id] = message;
          }
          return currentErrors;
        }, {});

        return errors;
      }

      function updateFieldState(field) {
        const input = document.getElementById(field.id);
        const errorElement = document.getElementById(`${field.id}-error`);
        const helperId = `${field.id}-helper`;
        const errorId = `${field.id}-error`;
        const error = field.validate(values[field.id]);

        if (error) {
