  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <div id="app"></div>
    </main>

    <script>
      const fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Jane Doe",
          validate(value) {
            return value.trim() ? "" : "Enter your full name.";
          }
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "jane@example.com",
          validate(value) {
            const trimmed = value.trim();
            if (!trimmed) {
              return "Enter your email address.";
            }
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
              ? ""
              : "Enter an email address in the format name@example.com.";
          }
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "(555) 123-4567",
          helper: "Optional. Use 10 digits, or include spaces, dashes, parentheses, and an optional country code.",
          validate(value) {
            const trimmed = value.trim();
            if (!trimmed) {
              return "";
            }
            return /^\+?[0-9][0-9\s().-]{8,18}$/.test(trimmed)
              ? ""
              : "Enter a phone number such as (555) 123-4567 or +1 555 123 4567.";
          }
        }
      ];

      let values = fields.reduce((currentValues, field) => {
        currentValues[field.id] = "";
        return currentValues;
      }, {});

      let errors = {};
      let submitted = false;

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#039;");
      }

      function Field({ field, value, error }) {
        const helperId = `${field.id}-helper`;
        const errorId = `${field.id}-error`;
        const describedBy = [
          field.helper ? helperId : "",
          error ? errorId : ""
        ].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}
              ${field.required
                ? '<span class="required-note">(required)</span>'
                : '<span class="optional-note">(optional)</span>'}
            </label>
            ${field.helper ? `<p class="helper-text" id="${helperId}">${field.helper}</p>` : ""}
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              autocomplete="${field.autocomplete}"
              placeholder="${field.placeholder}"
              value="${escapeHtml(value)}"
              ${field.required ? "required aria-required=\"true\"" : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              aria-invalid="${error ? "true" : "false"}"
            >
            <p class="error-message" id="${errorId}" aria-live="polite">${error || ""}</p>
          </div>
        `;
      }

      function SupportContactForm() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">Tell us who you are and how to reach you. Required fields are marked in text.</p>
            <form id="contact-form" novalidate>
              ${fields.map((field) => Field({
                field,
                value: values[field.id],
                error: errors[field.id]
              })).join("")}
              <button type="submit">Submit support request</button>
              <p class="form-status" id="form-status" tabindex="-1" aria-live="polite">
                ${submitted ? "Thanks. Your support request is ready to send." : ""}
              </p>
            </form>
          </section>
        `;
      }

      function validateFields() {
        errors = fields.reduce((currentErrors, field) => {
          const message = field.validate(values[field.id]);
          if (message) {
            currentErrors[field.id] = message;
          }
          return currentErrors;
        }, {});

        return errors;
      }

      function updateFieldState(field) {
        const input = document.getElementById(field.id);
        const errorElement = document.getElementById(`${field.id}-error`);
        const helperId = `${field.id}-helper`;
        const errorId = `${field.id}-error`;
        const error = field.validate(values[field.id]);

        if (error) {
          errors = { ...errors, [field.id]: error };
        } else {
          const { [field.id]: _removedError, ...remainingErrors } = errors;
          errors = remainingErrors;
        }

        input.setAttribute("aria-invalid", error ? "true" : "false");
        const describedBy = [field.helper ? helperId : "", error ? errorId : ""].filter(Boolean).join(" ");
        if (describedBy) {
          input.setAttribute("aria-describedby", describedBy);
        } else {
          input.removeAttribute("aria-describedby");
        }
        errorElement.textContent = error;
      }

      function render() {
        document.getElementById("app").innerHTML = SupportContactForm();

        fields.forEach((field) => {
          document.getElementById(field.id).addEventListener("input", (event) => {
            values = { ...values, [field.id]: event.target.value };
            submitted = false;
            document.getElementById("form-status").textContent = "";
            updateFieldState(field);
          });
        });

        document.getElementById("contact-form").addEventListener("submit", (event) => {
          event.preventDefault();
          validateFields();

          if (Object.keys(errors).length > 0) {
            const firstInvalidField = fields.find((field) => errors[field.id]);
            render();
            document.getElementById(firstInvalidField.id).focus();
            return;
          }

          submitted = true;
          render();
          document.getElementById("form-status").focus?.();
        });
      }

      render();
    </script>
  </body>
